   228→pub fn recover_matrix<P: Preset>(
   229→    partial_matrix: &[MatrixEntry<P>],
   230→    backend: KzgBackend,
   231→) -> Result<Vec<MatrixEntry<P>>> {
   232→    let mut partial_matrix_map = BTreeMap::new();
   233→    for matrix in partial_matrix {
   234→        partial_matrix_map
   235→            .entry(matrix.row_index)
   236→            .or_insert(Vec::new())
   237→            .push(matrix);
   238→    }
   239→
   240→    partial_matrix_map
   241→        .into_par_iter()
   242→        .map(|(_, entries)| {
   243→            let (cell_indices, cells): (Vec<_>, Vec<_>) =
   244→                entries.iter().map(|e| (e.column_index, &e.cell)).unzip();
   245→
   246→            recover_cells_and_kzg_proofs::<P>(cell_indices, cells, backend)
   247→        })
   248→        .collect::<Result<Vec<_>>>()
   249→        .map(construct_full_matrix)
   250→}
